params.command:
$ErrorActionPreference='Stop'
$src = Join-Path $env:USERPROFILE 'HeavenBridgeSource'
& git -C $src fetch origin main
if ($LASTEXITCODE -ne 0) { throw "fetch failed: $LASTEXITCODE" }
& git -C $src checkout -B main origin/main
if ($LASTEXITCODE -ne 0) { throw "checkout failed: $LASTEXITCODE" }
& git -C $src reset --hard origin/main
if ($LASTEXITCODE -ne 0) { throw "reset failed: $LASTEXITCODE" }
& git -C $src clean -fd -- heaven-bridge plugins/heaven-control-plane
if ($LASTEXITCODE -ne 0) { throw "clean failed: $LASTEXITCODE" }
$head = (& git -C $src rev-parse HEAD).Trim()
Write-Output "GATE_SOURCE=$head"
Push-Location $src
try {
  & python -m py_compile heaven-bridge/worker.py heaven-bridge/test_worker.py heaven-bridge/tests/test_worker.py
  if ($LASTEXITCODE -ne 0) { throw "py_compile failed: $LASTEXITCODE" }
  & python heaven-bridge/test_worker.py
  if ($LASTEXITCODE -ne 0) { throw "primary tests failed: $LASTEXITCODE" }
  & python heaven-bridge/tests/test_worker.py
  if ($LASTEXITCODE -ne 0) { throw "compat tests failed: $LASTEXITCODE" }
  & .\heaven-bridge\tests\Test-GitState.ps1
  if (-not $?) { throw 'git state regression failed' }
  & .\heaven-bridge\tests\Test-SecretEnvelopeIo.ps1
  if (-not $?) { throw 'secret envelope regression failed' }
  & python plugins/heaven-control-plane/verify.py
  if ($LASTEXITCODE -ne 0) { throw "control-plane verify failed: $LASTEXITCODE" }
  foreach ($path in @('heaven-bridge/bootstrap.ps1', 'heaven-bridge/manage.ps1', 'heaven-bridge/watchdog.ps1', 'heaven-bridge/sentinel.ps1', 'heaven-bridge/git-state.ps1', 'heaven-bridge/install-github-runner.ps1', 'heaven-bridge/uia.ps1', 'heaven-bridge/New-HeavenSecretEnvelope.ps1', 'heaven-bridge/secret-envelope-io.ps1', 'heaven-bridge/tests/Test-GitState.ps1', 'heaven-bridge/tests/Test-SecretEnvelopeIo.ps1')) {
    $tokens=$null; $errors=$null
    [void][System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path $path),[ref]$tokens,[ref]$errors)
    if ($errors.Count -gt 0) { throw ("PowerShell parse failed: {0}: {1}" -f $path, (($errors | ForEach-Object Message) -join '; ')) }
  }
  & python -c "import json,pathlib; p=json.loads(pathlib.Path('heaven-bridge/plugin/plugin.json').read_text()); c=json.loads(pathlib.Path('heaven-bridge/plugin/.codex-plugin/plugin.json').read_text()); assert p['name']=='heaven-local-bridge'; assert p['version']==c['version']=='0.8.2'; assert pathlib.Path('heaven-bridge/plugin/skills/heaven-bridge/SKILL.md').is_file(); assert pathlib.Path('heaven-bridge/plugin/skills/heaven-code-execution/SKILL.md').is_file(); assert pathlib.Path('heaven-bridge/plugin/skills/heaven-desktop-control/SKILL.md').is_file(); print('plugin', p['version'], 'ok')"
  if ($LASTEXITCODE -ne 0) { throw "plugin validation failed: $LASTEXITCODE" }
  Write-Output "HEAVEN_BRIDGE_FULL_GATE_OK source=$head"
} finally {
  Pop-Location
}
